package com.jbrempresa.backend.repository;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import com.jbrempresa.backend.entity.ContactoCanal;
public interface ContactoCanalRepository extends JpaRepository<ContactoCanal,Long>{List<ContactoCanal> findByEmpIdAndCocActTrueOrderByCocIde(Long empId);Optional<ContactoCanal> findByEmpIdAndCocId(Long empId,Long cocId);Optional<ContactoCanal> findByEmpIdAndCocCanAndCocIdeIgnoreCase(Long empId,String canal,String identidad);boolean existsByEmpIdAndCocCanAndCocIdeIgnoreCase(Long empId,String canal,String identidad);@Query(value="SELECT c.* FROM contactos_canal c WHERE c.emp_id=:cli AND c.coc_act=TRUE AND NOT EXISTS(SELECT 1 FROM personas_contactos_canal p WHERE p.emp_id=c.emp_id AND p.coc_id=c.coc_id AND p.pcc_act=TRUE) ORDER BY c.coc_fec_mov DESC",nativeQuery=true)List<ContactoCanal> sinIdentificar(@Param("cli")Long cli);}
